using System.Net.Http.Json;
using System.Text.Json;
using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop.Infrastructure.Management; public sealed class HttpSubscriptionManager(HttpClient client) : ISubscriptionManager { private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web); public async Task<IReadOnlyList<DesktopPlan>> PlansAsync(Guid org, CancellationToken ct) { Org(org); using var r = await client.GetAsync($"api/v1/organizations/{org:D}/subscriptions/plans", ct); r.EnsureSuccessStatusCode(); var v = await r.Content.ReadFromJsonAsync<List<DesktopPlan>>(Json, ct) ?? throw new InvalidOperationException("Empty plan response."); if (v.Count > 100 || v.Any(x => x.PlanId == Guid.Empty || x.Price < 0 || x.Currency.Length != 3)) throw new InvalidOperationException("Plan response is invalid."); return v; } public Task<DesktopSubscription> GetAsync(Guid org, Guid id, CancellationToken ct) => Get<DesktopSubscription>(org, id, "", ct); public Task<DesktopEntitlements> EntitlementsAsync(Guid org, Guid id, CancellationToken ct) => Get<DesktopEntitlements>(org, id, "/entitlements", ct); private async Task<T> Get<T>(Guid org, Guid id, string suffix, CancellationToken ct) { Org(org); if (id == Guid.Empty) throw new ArgumentException("Subscription is required."); using var r = await client.GetAsync($"api/v1/organizations/{org:D}/subscriptions/{id:D}{suffix}", ct); r.EnsureSuccessStatusCode(); return await r.Content.ReadFromJsonAsync<T>(Json, ct) ?? throw new InvalidOperationException("Empty subscription response."); } private static void Org(Guid org) { if (org == Guid.Empty) throw new ArgumentException("Organization is required."); } }
